#!/usr/bin/env python3
"""Bounded durable v2 Jev journal and legacy-compatible known-cost snapshot.

Uses only the standard library already present in the worker image. No prompts,
provider bodies or capability values enter the journal.
"""
import fcntl
import hashlib
import json
import math
import os
import sys
import struct
from pathlib import Path

MAX_CALLS = 10000

def call_cap():
    try:
        n = int(os.environ.get('FACTORY_JEV_RUN_MAX_CALLS', '300'))
        return min(n, MAX_CALLS) if n > 0 else 300
    except ValueError:
        return 300

def known(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0

def receipt_revision(rows, incomplete):
    # Hash the exact binary64 value, not a language's decimal JSON spelling.
    # Typed objects cannot collide with the fixed tuple/string/null row fields.
    def canonical(value):
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            number = float(value)
            if not math.isfinite(number):
                raise ValueError('non-finite accounting number')
            return {'$f64': struct.pack('>d', number).hex()}
        if isinstance(value, list):
            return [canonical(v) for v in value]
        return value
    encoded = json.dumps(canonical([rows, incomplete]), separators=(',', ':'), ensure_ascii=False)
    return hashlib.sha256(encoded.encode()).hexdigest()

def accounting_json(text):
    # JavaScript parses every JSON number as binary64, including integer tokens.
    # Matching that boundary also keeps summation and hash inputs consistent.
    return json.loads(text, parse_int=float, parse_float=float)

def subtotal_text(value):
    # Keep the old six-decimal presentation only when it preserves the bill.
    fixed = format(value, '.6f')
    return fixed if float(fixed) == value else json.dumps(value)

def append(out, record):
    out.mkdir(parents=True, exist_ok=True)
    target = out / 'jev-accounting.jsonl'
    with open(str(target)+'.lock', 'a', encoding='utf-8') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        line = json.dumps(record, separators=(',', ':'), sort_keys=True)+'\n'
        if len(line.encode()) > 16384:
            raise ValueError('receipt too large')
        if target.exists():
            if target.stat().st_size > 2*call_cap()*16384:
                raise ValueError('journal full')
            with target.open(encoding='utf-8') as prior:
                if sum(1 for _ in prior) >= 2*call_cap():
                    raise ValueError('journal full')
        fd = os.open(target, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o600)
        try:
            data = line.encode()
            while data:
                data = data[os.write(fd, data):]
            os.fsync(fd)
        finally:
            os.close(fd)
        directory = os.open(out, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)

def snapshot(out):
    attempts, submissions, resolved = {}, set(), set()
    incomplete = False
    target = out / 'jev-accounting.jsonl'
    if target.exists():
        try:
            if target.stat().st_size > 2*MAX_CALLS*16384:
                raise ValueError('journal exceeds maximum')
            with target.open(encoding='utf-8') as journal:
                for line in journal:
                    try:
                        r = accounting_json(line)
                        if r.get('version') != 2:
                            raise ValueError('legacy')
                        decision = r.get('decisionId')
                        if r.get('event') == 'submission':
                            submissions.add(decision)
                            continue
                        resolved.add(decision)
                        if r.get('event') == 'denied':
                            continue
                        identity = r.get('attemptId')
                        if not identity or not decision:
                            raise ValueError('unidentified receipt')
                        bound=[r.get('inputHash'),r.get('questionHash'),r.get('questionRevision'),r.get('requestedModel'),r.get('schemaRevision'),r.get('gateRevision')]
                        a = attempts.setdefault(identity, {'decision': decision, 'admitted': False, 'settled': None, 'conflict': False, 'binding': bound})
                        a['conflict'] |= a['binding'] != bound
                        a['conflict'] |= a['decision'] != decision
                        if r.get('event') == 'admitted':
                            a['admitted'] = True
                        if r.get('event') == 'settled':
                            # Proxy mirrors carry authoritative admitted identity;
                            # runner independently reconciles them on result intake.
                            a['admitted'] |= r.get('recordSource') == 'comparison'
                            a['conflict'] |= a['settled'] is not None and a['settled'] != r
                            a['settled'] = r
                    except (ValueError, TypeError, AttributeError):
                        incomplete = True
        except (OSError, ValueError):
            incomplete = True
    incomplete |= bool(submissions-resolved)
    jev_cost, worker_cost, unknown, rows = 0, 0, 0, []
    for identity, a in sorted(attempts.items()):
        s = a['settled'] or {}
        complete = a['admitted'] and not a['conflict'] and (s.get('dispatchState') == 'not_dispatched' or (s.get('costStatus') == 'provider-reported' and known(s.get('costUsd'))))
        if not complete:
            unknown += 1
        if not a['conflict'] and s.get('costStatus') == 'provider-reported' and known(s.get('costUsd')):
            jev_cost += s['costUsd']
        binding=json.dumps([s.get('inputHash'),s.get('questionHash'),s.get('questionRevision'),s.get('requestedModel'),s.get('schemaRevision'),s.get('gateRevision')],separators=(',',':'),ensure_ascii=False)
        rows.append([identity, a['decision'], a['admitted'], a['conflict'], s.get('dispatchState'), s.get('costStatus'), s.get('costUsd'), s.get('disposition'),binding,s.get('resolvedModel')])
    for file in sorted(out.glob('*-*.json')):
        if not (file.name.endswith('-result.json') or file.name.endswith('-error.json')):
            continue
        try:
            r = accounting_json(file.read_text())
            if file.name.startswith('jev-'):
                if r.get('attemptId') not in attempts:
                    cost = r.get('total_cost_usd')
                    if cost is None:
                        cost = r.get('known_cost_usd', r.get('costUsd'))
                    if known(cost):
                        jev_cost += cost
                    if r.get('version') == 2 or known(cost) or r.get('cost_source') == 'unknown' or r.get('costSource') == 'unknown':
                        incomplete = True
                continue
            cost = r.get('total_cost_usd')
            if cost is None:
                cost = r.get('known_cost_usd')
            if known(cost):
                worker_cost += cost
            if r.get('cost_source') == 'unknown' or (r.get('total_cost_usd', False) is None and known(r.get('known_cost_usd'))):
                incomplete = True
            rows.append([file.name, cost, r.get('cost_source')])
        except (ValueError, OSError, AttributeError):
            incomplete = True
    incomplete |= unknown > 0 or (out / '.jev-accounting-incomplete').exists()
    revision = receipt_revision(rows, incomplete)
    return dict(dispatchedAttemptCount=sum(a['admitted'] and (a['settled'] or {}).get('dispatchState') != 'not_dispatched' for a in attempts.values()), knownCostUsd=worker_cost+jev_cost, knownJevCostUsd=jev_cost, unknownAttemptCount=unknown, costCoverage='incomplete' if incomplete else 'complete', receiptRevision=revision)

if __name__ == '__main__':
    directory = Path(os.environ.get('FACTORY_OUT_DIR', '/out'))
    try:
        if sys.argv[1] == 'append':
            append(directory, json.load(sys.stdin))
        elif sys.argv[1] == 'subtotal':
            print(subtotal_text(snapshot(directory)['knownCostUsd']))
        else:
            print(json.dumps(snapshot(directory), separators=(',', ':')))
    except (OSError, ValueError, TypeError):
        # Fail closed for further auxiliary dispatch; retain the temporary
        # receipt if append failed. The existing caller still falls back.
        try:
            (directory / '.jev-accounting-incomplete').touch()
        except OSError:
            pass
        sys.exit(2)

