process.env.FACTORY_DATA = root;
process.env.FACTORY_RUNS_DIR = join(root, 'runs');
process.env.FACTORY_REPOS_FILE = join(root, 'repos.json');
const { db } = await import('./db.js');
const { parseFinishResult, finish } = await import('./queue.js');
const { readJevRunAccounting, appendJevAccounting, jevJournalPath } = await import('./jev-accounting.js');
const { mintJevCapability, resetJevCapabilitiesForTests, jevRunLedgerSnapshot } = await import('./jev-proxy.js');
const { beginJevRequest, jevDecideRoute } = await import('./jev-http.js');
