	{ mode: 'known-error', label: 'small-exponent', cost: 1e-7 },
	{ mode: 'known-error', label: 'fine-precision', cost: 1.2345678901234567e-7 },
	{ mode: 'known-error', label: 'known-zero', cost: 0 },
	{ mode: 'known-error', label: 'subnormal', cost: Number.MIN_VALUE },
	{ mode: 'known-error', label: 'binary-fraction', cost: 0.1 + 0.2 },
	{ mode: 'unknown', label: 'unknown', cost: 0 },
	{ mode: 'denied', label: 'denied', cost: 0 }
];
for (const { mode, label, cost } of costScenarios) {
	test(`A08 actual guard cleanup → all worker emitters → queue settlement (${label})`, async () => {
		resetJevCapabilitiesForTests();
		let calls = 0;
		process.env.FACTORY_OPENROUTER_API_KEY = 'loopback-only';
		const provider = createServer(async (req, res) => {
			calls++;
			let body = '';
			for await (const c of req) body += c;
			const q = JSON.parse(body).questions as Record<string, unknown>;
			res.end(
				JSON.stringify({
					model: 'fixture',
					answers: Object.fromEntries(Object.keys(q).map((k) => [k, { type: 'noul', noul: mode === 'known-error' ? 2 : 0 }])),
					usage: { input_tokens: 2, output_tokens: 1, ...(mode === 'known-error' ? { cost } : {}) }
				})
			);
		});
		await new Promise<void>((r) => provider.listen(0, '127.0.0.1', r));
		const pa = provider.address();
		assert.ok(pa && typeof pa === 'object');
		process.env.FACTORY_JEV_ENDPOINT = `http://127.0.0.1:${pa.port}`;
		let token = '';
		const app = express();
		app.use(beginJevRequest);
		app.use(express.json());
		app.use((_req, res, next) => {
			if (mode === 'denied') {
				res.status(401).json({ ok: false, reason: 'unauthorized' });
				return;
			}
			res.locals.capability = 'jev';
			res.locals.jevToken = token;
			next();
		});
		app.post('/jev/decide', jevDecideRoute);
		const server = createServer(app);
		await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
		const sa = server.address();
		assert.ok(sa && typeof sa === 'object');
		try {
			for (const worker of ['run', 'spec', 'reconcile']) {
				const id = `account-${label}-${worker}`,
					out = join(root, 'runs', id);
				mkdirSync(out, { recursive: true });
				seed(id);
				token = mintJevCapability(id);
				reserveStageSpend(
					{
						runId: id,
						phase: 'fixture',
						attempt: 1,
						provider: 'claude',
						model: 'sonnet',
						estimatedUsd: 1,
						costSource: 'provider-reported'
					},
					null
				);
				const hook = exec('bash', [resolve('../agent/hooks/jev-guard.sh')], {
					cwd: out,
					env: {
						PATH: '/usr/bin:/bin',
						HOME: out,
						FACTORY_OUT_DIR: out,
						FACTORY_RUN_ID: id,
						FACTORY_JEV_GUARD: 'shadow',
						FACTORY_JEV_LIB: resolve('../agent/lib/jev.sh'),
						FACTORY_JEV_PROXY_URL: `http://127.0.0.1:${sa.port}`,
						FACTORY_JEV_CAPABILITY: token
					}
				});
				hook.child.stdin?.end(JSON.stringify({ tool_name: 'Bash', cwd: '/work', tool_input: { command: 'git status' } }));
				await hook;
				assert.equal(
					readdirSync(out).some((f) => f.startsWith('jev-guard-') && (f.endsWith('-result.json') || f.endsWith('-error.json'))),
					false,
					'guard removed temporary receipt'
				);
				const source = readFileSync(resolve(`../agent/${worker}.sh`), 'utf8');
				const emitter = source.match(/\nemit\(\) \{[\s\S]*?\n\}/)?.[0];
				assert.ok(emitter);
				const script = join(out, 'emit.sh');
				writeFileSync(
					script,
					`. "$1"\n${emitter}\nRESULT="$FACTORY_OUT_DIR/result.json"; test_exit=0; note=fixture; CODEX_CALLS=0; SPEC_ID=fixture; SPEC_COMMIT_SHA=; emit\n`
				);
				await exec('bash', [script, resolve('../agent/lib/cost.sh')], {
					cwd: out,
					env: { ...process.env, FACTORY_OUT_DIR: out, FACTORY_RUN_ID: id }
				});
				const result = parseFinishResult(JSON.parse(readFileSync(join(out, 'result.json'), 'utf8')));
				assert.equal(result.costUsd, mode === 'known-error' ? cost : 0);
				assert.equal(result.knownCostUsd, result.costUsd);
				assert.equal(result.unknownAttemptCount, mode === 'unknown' ? 1 : 0);
				assert.equal(result.costCoverage, mode === 'unknown' ? 'incomplete' : 'complete');
				finish(id, 0, out);
				const stored = db.prepare('SELECT cost_usd,status FROM runs WHERE id=?').get(id) as { cost_usd: number; status: string };
				assert.equal(stored.cost_usd, result.knownCostUsd);
				assert.equal(stored.status, 'passed');
				const reservation = db.prepare('SELECT settled_at,actual_usd FROM budget_reservations WHERE run_id=?').get(id) as {
					settled_at: string | null;
					actual_usd: number | null;
				};
				assert.equal(reservation.settled_at === null, mode === 'unknown');
				if (mode !== 'unknown') assert.equal(reservation.actual_usd, result.knownCostUsd);
				const accounting = readJevRunAccounting(id, out);
				assert.equal(accounting.unknownAttemptCount, mode === 'unknown' ? 1 : 0);
				assert.equal(accounting.costCoverage, mode === 'unknown' ? 'incomplete' : 'complete');
				assert.equal(accounting.knownCostUsd, result.knownCostUsd);
				assert.equal(accounting.receiptRevision, result.receiptRevision);
				assert.equal(accounting.admittedAttemptCount, mode === 'denied' ? 0 : 1);
			}
			assert.equal(calls, mode === 'denied' ? 0 : 3);
		} finally {
			server.closeAllConnections();
			provider.closeAllConnections();
			await new Promise<void>((r) => server.close(() => r()));
			await new Promise<void>((r) => provider.close(() => r()));
		}
	});
}

test('A08 late authoritative receipt invalidates terminal stats and settles retained exposure once', () => {
	const id = 'late-account',
		out = join(root, 'runs', id);
	mkdirSync(out, { recursive: true });
	seed(id);
	reserveStageSpend(
		{ runId: id, phase: 'fixture', attempt: 1, provider: 'claude', model: 'sonnet', estimatedUsd: 1, costSource: 'provider-reported' },
		null
	);
	const admitted = {
		version: 2 as const,
		event: 'admitted' as const,
		recordSource: 'authoritative' as const,
		runId: id,
		decisionId: 'logical-late',
		attemptId: 'attempt-late',
		dispatchState: 'possibly_dispatched' as const
	};
	appendJevAccounting(admitted, 2);
	const coverage = readJevRunAccounting(id, out);
	writeFileSync(join(out, 'result.json'), JSON.stringify({ ...coverage, costUsd: 0, testExit: 0 }));
	finish(id, 0, out);
	const run = db.prepare('SELECT * FROM runs WHERE id=?').get(id) as import('./db.js').Run;
	assert.equal(runStageNums(run).jev.costUsd, 0);
	const before = computeStats();
	const settlement = {
		...admitted,
		event: 'settled' as const,
		dispatchState: 'received' as const,
		costUsd: 0.02,
		costStatus: 'provider-reported' as const,
		disposition: 'success'
	};
	appendJevAccounting(settlement, 2);
	assert.equal(runStageNums(run).jev.costUsd, 0.02);
	assert.notStrictEqual(computeStats(), before);
	assert.equal((db.prepare('SELECT cost_usd FROM runs WHERE id=?').get(id) as { cost_usd: number }).cost_usd, 0.02);
	assert.ok((db.prepare('SELECT settled_at FROM budget_reservations WHERE run_id=?').get(id) as { settled_at: string | null }).settled_at);
	appendJevAccounting(settlement, 2);
	assert.equal(readJevRunAccounting(id, out).knownCostUsd, 0.02);
	assert.equal(runStageNums(run).jev.costUsd, 0.02);
});
