		'5e-324',
		'2.2250738585072014e-308',
		'1e-7',
		'1e-6',
		'0.0001',
		'0.01',
		'0.30000000000000004',
		'1.0000000000000002',
		'9007199254740993',
		'1000000000000000100',
		'1e20',
		'1e21',
		'1.7976931348623157e308',
		'null'
	];
	const input = '[' + lexemes.join(',') + ']';
	const rows = JSON.parse(input) as unknown[];
	const { jevReceiptRevision } = await import('./jev-accounting.js');
	const python = exec('/usr/bin/python3', [
		'-B',
		'-c',
		`import importlib.util,sys
spec=importlib.util.spec_from_file_location('accounting',sys.argv[1]);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
rows=module.accounting_json(sys.stdin.read());print(module.receipt_revision(rows,False));print(module.receipt_revision(rows,True))`,
		resolve('../agent/lib/jev-accounting.py')
	]);
	python.child.stdin?.end(input);
	const hashes = (await python).stdout.trim().split('\n');
	assert.equal(hashes[0], jevReceiptRevision(rows, false));
	assert.equal(hashes[1], jevReceiptRevision(rows, true));
