// Durable, bounded Jev receipts. Admission is fsynced before inference; a
// missing settlement is exposure, never a zero bill. No prompts or credentials.
import { createHash } from 'node:crypto';
import { closeSync, existsSync, fsyncSync, mkdirSync, openSync, readFileSync, readdirSync, unlinkSync, writeSync } from 'node:fs';
import { writeFileSync, unlinkSync as removeReceipt } from 'node:fs';
