export type CostCoverage = {
	knownCostUsd: number;
	unknownAttemptCount: number;
	costCoverage: 'complete' | 'incomplete';
	receiptRevision: string;
};
export type JevAccountingRecord = Partial<JevRecordIdentity> & {
	version: 2;
	event: 'admitted' | 'settled' | 'submission' | 'denied';
	recordSource: 'authoritative' | 'comparison';
	runId: string;
	decisionId: string;
	attemptId?: string;
	site?: string;
	dispatchState?: 'not_dispatched' | 'possibly_dispatched' | 'received';
	costUsd?: number | null;
	costStatus?: string;
	disposition?: string;
};
const RUN_ID = /^[A-Za-z0-9_:-]{1,128}$/;
export const MAX_JEV_CALLS = 10_000;
export function jevRunCallCap(): number {
	const n = Number(process.env.FACTORY_JEV_RUN_MAX_CALLS);
	return Number.isSafeInteger(n) && n > 0 ? Math.min(n, MAX_JEV_CALLS) : 300;
}
export function jevJournalPath(runId: string): string {
	if (!RUN_ID.test(runId)) throw new Error('invalid Jev run identity');
	return join(process.env.FACTORY_DATA ?? '/data', 'jev-accounting', `${runId}.jsonl`);
}
let revision = 0;
const failedJournals = new Set<string>();
const listeners = new Set<(runId: string) => void>();
export const jevAccountingRevision = (): number => revision;
export function onJevAccountingChange(listener: (runId: string) => void): () => void {
	listeners.add(listener);
	return () => {
		listeners.delete(listener);
	};
}
export function appendJevAccounting(record: JevAccountingRecord, cap: number): void {
	const file = jevJournalPath(record.runId);
	mkdirSync(join(file, '..'), { recursive: true, mode: 0o700 });
	const lock = `${file}.lock`;
	let lockFd: number;
	try {
		lockFd = openSync(lock, 'wx', 0o600);
	} catch (error) {
		failedJournals.add(record.runId);
		throw error;
	}
	let fd: number | undefined;
	try {
		const line = JSON.stringify(record) + '\n';
		if (Buffer.byteLength(line) > 16_384) throw new Error('Jev receipt too large');
		const prior = existsSync(file) ? readFileSync(file, 'utf8') : '';
		if (prior.length > 2 * cap * 16_384 || prior.split('\n').filter(Boolean).length >= 2 * cap) throw new Error('Jev journal full');
		fd = openSync(file, 'a', 0o600);
		const bytes = Buffer.from(line);
		let written = 0;
		while (written < bytes.length) written += writeSync(fd, bytes, written, bytes.length - written);
		fsyncSync(fd);
		// Persist directory creation too; the journal must outlive worker temp cleanup.
		const dir = openSync(join(file, '..'), 'r');
		try {
			fsyncSync(dir);
		} finally {
			closeSync(dir);
		}
		revision++;
		for (const listener of listeners) {
			try {
				listener(record.runId);
			} catch {
				console.warn(`[jev] accounting refresh failed run=${record.runId}`);
			}
		}
	} catch (error) {
		failedJournals.add(record.runId);
		try {
			writeFileSync(`${file}.incomplete`, '', { mode: 0o600 });
		} catch {
			/* in-memory fence remains */
		}
		throw error;
	} finally {
		if (fd !== undefined) closeSync(fd);
		closeSync(lockFd);
		unlinkSync(lock);
	}
}
function pendingPath(record: JevAccountingRecord): string {
	if (!record.attemptId || !/^[A-Za-z0-9_-]{1,128}$/.test(record.attemptId)) throw new Error('invalid settlement identity');
	return `${jevJournalPath(record.runId)}.pending-${record.attemptId}`;
}
/** Retain the already-received provider facts until the journal fsync succeeds.
 * Reconciliation below replays receipts only, never an inference. */
export function persistJevSettlement(record: JevAccountingRecord, cap: number): void {
	const pending = pendingPath(record);
	const line = JSON.stringify(record) + '\n';
	if (Buffer.byteLength(line) > 16_384) throw new Error('Jev receipt too large');
	let retained = false;
	try {
		const fd = openSync(pending, 'w', 0o600);
		try {
			const bytes = Buffer.from(line);
			let offset = 0;
			while (offset < bytes.length) offset += writeSync(fd, bytes, offset, bytes.length - offset);
			fsyncSync(fd);
			retained = true;
		} finally {
			closeSync(fd);
		}
		const directory = openSync(join(pending, '..'), 'r');
		try {
			fsyncSync(directory);
		} finally {
			closeSync(directory);
		}
	} catch {
		/* append may still persist the receipt; otherwise admission stays unknown */
	}
	appendJevAccounting(record, cap);
	if (retained) {
		try {
			removeReceipt(pending);
		} catch (error) {
			if (!(error instanceof Error && 'code' in error && error.code === 'ENOENT')) throw error;
		}
	}
}
const reconciling = new Set<string>();
function reconcilePendingJevReceipts(runId: string): void {
	if (reconciling.has(runId)) return;
	const journal = jevJournalPath(runId),
		directory = join(journal, '..'),
		prefix = `${runId}.jsonl.pending-`;
	if (!existsSync(directory)) return;
	const pending = readdirSync(directory)
		.filter((file) => file.startsWith(prefix))
		.slice(0, MAX_JEV_CALLS);
	if (!pending.length) return;
	reconciling.add(runId);
	let failed = false;
	for (const name of pending) {
		const file = join(directory, name);
		try {
			const bytes = readFileSync(file);
			if (bytes.length > 16_384) throw new Error('oversize settlement');
			const value: unknown = JSON.parse(bytes.toString('utf8'));
			if (
				!object(value) ||
				value.version !== 2 ||
				value.event !== 'settled' ||
				value.recordSource !== 'authoritative' ||
				value.runId !== runId ||
				typeof value.decisionId !== 'string' ||
				typeof value.attemptId !== 'string'
			)
				throw new Error('invalid retained receipt');
			const prior = readRecords(journal);
			if (prior.incomplete) throw new Error('corrupt admission journal');
			const admitted = prior.records.find(
				(r) => r.event === 'admitted' && r.attemptId === value.attemptId && r.decisionId === value.decisionId
			);
			if (!admitted) throw new Error('unbound retained receipt');
			const settled = prior.records.find((r) => r.event === 'settled' && r.attemptId === value.attemptId);
			if (settled && settlementBinding(settled) !== settlementBinding(value)) throw new Error('conflicting retained receipt');
			if (!settled) appendJevAccounting(value as JevAccountingRecord, MAX_JEV_CALLS);
			removeReceipt(file);
		} catch {
			failed = true;
		}
	}
	reconciling.delete(runId);
	if (!failed) {
		failedJournals.delete(runId);
		try {
			removeReceipt(`${journal}.incomplete`);
		} catch {
			/* no failure marker */
		}
		revision++;
		for (const listener of listeners) {
			try {
				listener(runId);
			} catch {
				console.warn(`[jev] reconciled accounting refresh failed run=${runId}`);
			}
		}
	}
}
export function markJevRunRetired(runId: string): void {
	const file = `${jevJournalPath(runId)}.retired`;
	mkdirSync(join(file, '..'), { recursive: true, mode: 0o700 });
	const fd = openSync(file, 'a', 0o600);
	try {
		fsyncSync(fd);
	} finally {
		closeSync(fd);
	}
	const dir = openSync(join(file, '..'), 'r');
	try {
		fsyncSync(dir);
	} finally {
		closeSync(dir);
	}
}
export function jevRunWasRetired(runId: string): boolean {
	return existsSync(`${jevJournalPath(runId)}.retired`);
}
export function settledJevRecord(result: JevResult, runId: string): JevAccountingRecord {
	return {
		version: 2,
		origin: result.origin,
		requestedModel: result.requestedModel,
		resolvedModel: result.resolvedModel,
		inputHash: result.inputHash,
		questionHash: result.questionHash,
		questionRevision: result.questionRevision,
		schemaRevision: result.schemaRevision,
		gateRevision: result.gateRevision,
		startedAt: result.startedAt,
		completedAt: result.completedAt,
		event: 'settled',
		recordSource: 'authoritative',
		runId,
		decisionId: result.decisionId!,
		attemptId: result.attemptId!,
		site: result.site,
		dispatchState: result.dispatchState,
		costUsd: result.costUsd ?? null,
		costStatus: result.costSource ?? 'unknown',
		disposition: result.disposition
	};
}
function object(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function known(value: unknown): value is number {
	return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}
function readRecords(file: string): { records: Record<string, unknown>[]; incomplete: boolean } {
	if (!existsSync(file)) return { records: [], incomplete: false };
	try {
		const bytes = readFileSync(file);
		if (bytes.length > 2 * MAX_JEV_CALLS * 16_384) return { records: [], incomplete: true };
		const records: Record<string, unknown>[] = [];
		let incomplete = false;
		for (const line of bytes.toString('utf8').split('\n').filter(Boolean)) {
			try {
				const r: unknown = JSON.parse(line);
				if (object(r) && r.version === 2) records.push(r);
				else incomplete = true;
			} catch {
				incomplete = true;
			}
		}
		return { records, incomplete };
	} catch {
		return { records: [], incomplete: true };
	}
}
function inputBinding(r: Record<string, unknown>): string {
	return JSON.stringify([
		r.inputHash ?? null,
		r.questionHash ?? null,
		r.questionRevision ?? null,
		r.requestedModel ?? null,
		r.schemaRevision ?? null,
		r.gateRevision ?? null
	]);
}
function settlementBinding(r: Record<string, unknown>): string {
	return JSON.stringify([
		r.runId,
		r.decisionId,
		r.attemptId,
		r.dispatchState,
		r.costStatus,
		r.costUsd,
		r.disposition,
		inputBinding(r),
		r.resolvedModel ?? null
	]);
}
/** Exact binary64 encoding makes receipt numbers independent of Python/JS
 * decimal JSON formatting. The persisted bill itself is never quantized. */
export function jevReceiptRevision(rows: unknown[], incomplete: boolean): string {
	const canonical = (value: unknown): unknown => {
		if (typeof value === 'number') {
			if (!Number.isFinite(value)) throw new Error('non-finite accounting number');
			const bytes = Buffer.allocUnsafe(8);
			bytes.writeDoubleBE(value);
			return { $f64: bytes.toString('hex') };
		}
		return Array.isArray(value) ? value.map(canonical) : value;
	};
	return createHash('sha256')
		.update(JSON.stringify(canonical([rows, incomplete])))
		.digest('hex');
}

/** Authoritative journal overrides mirrors only on matching decision/attempt
 * bindings. Conflicts quarantine the bill instead of choosing the largest. */
export function readJevRunAccounting(
	runId: string,
	outDir?: string
): CostCoverage & { knownJevCostUsd: number; admittedAttemptCount: number; dispatchedAttemptCount: number } {
	reconcilePendingJevReceipts(runId);
	const authoritative = readRecords(jevJournalPath(runId));
	const local = outDir ? readRecords(join(outDir, 'jev-accounting.jsonl')) : { records: [], incomplete: false };
	let incomplete =
		failedJournals.has(runId) ||
		existsSync(`${jevJournalPath(runId)}.incomplete`) ||
		authoritative.incomplete ||
		local.incomplete ||
		Boolean(outDir && existsSync(join(outDir, '.jev-accounting-incomplete')));
	const authoritativeRows = new Set(authoritative.records);
	const authoritativeAttempts = new Set(authoritative.records.map((r) => r.attemptId));
	const authoritativeDecisions = new Set(
		[...authoritative.records, ...local.records.filter((r) => r.event === 'denied')].map((r) => r.decisionId)
	);
	const attempts = new Map<
		string,
		{ decisionId: string; admitted: boolean; settled?: Record<string, unknown>; conflict: boolean; binding?: string }
	>();
	const canonicalRows: unknown[] = [];
	for (const r of [...authoritative.records, ...local.records]) {
		if (r.runId !== runId && r.runId !== '') {
			incomplete = true;
			continue;
		}
		if (r.event === 'submission') {
			if (!authoritativeDecisions.has(r.decisionId)) incomplete = true;
			continue;
		}
		if (r.event === 'denied') continue;
		if (typeof r.attemptId !== 'string' || typeof r.decisionId !== 'string') {
			incomplete = true;
			continue;
		}
		if (r.recordSource === 'comparison') {
			if (!authoritativeAttempts.has(r.attemptId)) incomplete = true;
			const prior = attempts.get(r.attemptId);
			if (
				prior &&
				(prior.decisionId !== r.decisionId ||
					prior.binding !== inputBinding(r) ||
					(r.costStatus === 'provider-reported' &&
						prior.settled?.costStatus === 'provider-reported' &&
						r.costUsd !== prior.settled.costUsd))
			)
				prior.conflict = true;
			continue;
		}
		const prior = attempts.get(r.attemptId) ?? { decisionId: r.decisionId, admitted: false, conflict: false, binding: inputBinding(r) };
		if (prior.binding !== inputBinding(r)) prior.conflict = true;
		if (prior.decisionId !== r.decisionId) prior.conflict = true;
		if (!authoritativeRows.has(r)) incomplete = true; // Direct shell receipts are not run-cap qualified.
		if (r.event === 'admitted') prior.admitted = true;
		if (r.event === 'settled') {
			if (prior.settled && settlementBinding(prior.settled) !== settlementBinding(r)) prior.conflict = true;
			else prior.settled = r;
		}
		attempts.set(r.attemptId, prior);
	}
	let jevCost = 0,
		unknown = 0,
		workerCost = 0;
	for (const [id, a] of [...attempts].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
		const s = a.settled;
		const complete =
			a.admitted &&
			!a.conflict &&
			s &&
			(s.dispatchState === 'not_dispatched' || (s.costStatus === 'provider-reported' && known(s.costUsd)));
		if (!complete) unknown++;
		if (!a.conflict && s?.costStatus === 'provider-reported' && known(s.costUsd)) jevCost += s.costUsd;
		canonicalRows.push([
			id,
			a.decisionId,
			a.admitted,
			a.conflict,
			s?.dispatchState ?? null,
			s?.costStatus ?? null,
			s?.costUsd ?? null,
			s?.disposition ?? null,
			inputBinding(s ?? {}),
			s?.resolvedModel ?? null
		]);
	}
	if (outDir && existsSync(outDir)) {
		for (const file of readdirSync(outDir).sort()) {
			if (!file.endsWith('-result.json') && !file.endsWith('-error.json')) continue;
			try {
				const r: unknown = JSON.parse(readFileSync(join(outDir, file), 'utf8'));
				if (!object(r)) {
					incomplete = true;
					continue;
				}
				if (file.startsWith('jev-')) {
					if (typeof r.attemptId !== 'string' || !attempts.has(r.attemptId)) {
						// Denied submissions are not provider attempts. Idless legacy bills stay unqualified.
						if (known(r.total_cost_usd ?? r.known_cost_usd ?? r.costUsd))
							jevCost += Number(r.total_cost_usd ?? r.known_cost_usd ?? r.costUsd);
						if (
							r.version === 2 ||
							known(r.total_cost_usd ?? r.known_cost_usd ?? r.costUsd) ||
							r.cost_source === 'unknown' ||
							r.costSource === 'unknown'
						)
							incomplete = true;
					}
					continue;
				}
				const cost = r.total_cost_usd ?? r.known_cost_usd;
				if (known(cost)) workerCost += cost;
				if (r.cost_source === 'unknown' || (r.total_cost_usd === null && known(r.known_cost_usd))) incomplete = true;
				canonicalRows.push([file, cost ?? null, r.cost_source ?? null]);
			} catch {
				incomplete = true;
			}
		}
	}
	incomplete ||= unknown > 0;
	return {
		knownCostUsd: workerCost + jevCost,
		knownJevCostUsd: jevCost,
		unknownAttemptCount: unknown,
		admittedAttemptCount: [...attempts.values()].filter((a) => a.admitted).length,
		dispatchedAttemptCount: [...attempts.values()].filter((a) => a.admitted && a.settled?.dispatchState !== 'not_dispatched').length,
		costCoverage: incomplete ? 'incomplete' : 'complete',
		receiptRevision: jevReceiptRevision(canonicalRows, incomplete)
	};
}

