import type { Request, RequestHandler } from 'express';
import { handleJevDecideRequest } from './jev-proxy.js';
const lifetimes = new WeakMap<Request, { start: number; controller: AbortController; cleanup: () => void }>();
/** Install before express.json: normal request close means body completion,
 * whereas aborted input or an unfinished response close means cancellation. */
export const beginJevRequest: RequestHandler = (req, res, next) => {
	if (req.path !== '/jev/decide') return next();
	const controller = new AbortController(),
		start = performance.now();
	const abort = () => controller.abort(new DOMException('Client disconnected', 'AbortError'));
	const close = () => {
		if (!res.writableEnded) abort();
		cleanup();
	};
	const cleanup = () => {
		req.removeListener('aborted', abort);
		res.removeListener('close', close);
		res.removeListener('finish', cleanup);
	};
	lifetimes.set(req, { start, controller, cleanup });
	req.once('aborted', abort);
	res.once('close', close);
	res.once('finish', cleanup);
	if (req.aborted) abort();
	next();
};
export const jevDecideRoute: RequestHandler = async (req, res, next) => {
	if (res.locals.capability !== 'jev') {
		res.status(403).json({ error: 'forbidden' });
		return;
	}
	const lifetime = lifetimes.get(req);
	const body = req.body as unknown;
	const duration = typeof body === 'object' && body !== null && 'remainingMs' in body ? body.remainingMs : undefined;
	const remainingMs =
		typeof duration === 'number' ? Math.max(0, duration - (performance.now() - (lifetime?.start ?? performance.now()))) : undefined;
	try {
		const outcome = await handleJevDecideRequest(res.locals.jevToken as string, body, { signal: lifetime?.controller.signal, remainingMs });
		if (!res.destroyed && !res.writableEnded) res.status(outcome.status).json(outcome.body);
	} catch (error) {
		next(error);
	} finally {
		lifetime?.cleanup();
		lifetimes.delete(req);
	}
};
